package com.xdownload.mobile;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
public final class ToolsActivity extends Activity{
 final ExecutorService io=Executors.newSingleThreadExecutor();TextView status;Button select,save,zip;Spinner operation;EditText password;Uri source;File result;String resultName="";boolean busy=false,dead=false;int selected;
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,24,24,24);TextView title=new TextView(this);title.setText("Local file tools");title.setTextSize(23);l.addView(title);operation=new Spinner(this);operation.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Encrypt file (AES-256)","Decrypt vault file","Extract ZIP (into Downloads)"}));l.addView(operation);password=new EditText(this);password.setHint("Vault password (8+ characters)");password.setInputType(129);l.addView(password);select=new Button(this);select.setText("Choose file and run");select.setOnClickListener(v->{if(!busy){selected=operation.getSelectedItemPosition();startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),10);}});l.addView(select);zip=new Button(this);zip.setText("Create ZIP from selected files");zip.setOnClickListener(v->{if(!busy)startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true),12);});l.addView(zip);save=new Button(this);save.setText("Save result");save.setEnabled(false);save.setOnClickListener(v->{if(!busy&&result!=null)startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(resultName.endsWith(".zip")?"application/zip":"application/octet-stream").putExtra(Intent.EXTRA_TITLE,resultName),11);});l.addView(save);status=new TextView(this);status.setText("Original files are kept. Vault passwords cannot be recovered. ZIP only; bounded extraction. Keep this screen open.");l.addView(status);setContentView(l);}
 void state(boolean b,String msg){busy=b;select.setEnabled(!b);zip.setEnabled(!b);operation.setEnabled(!b);password.setEnabled(!b);save.setEnabled(!b&&result!=null);status.setText(msg);}
 String name(Uri uri){try(android.database.Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())return HttpEngine.safeName(c.getString(0));}catch(Exception ignored){}return "file";}
 void copy(InputStream in,OutputStream out,long limit)throws IOException{if(in==null||out==null)throw new IOException("Cannot access file");byte[] b=new byte[65536];long total=0;int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException("Cancelled");total+=n;if(total>limit)throw new IOException("File size limit");out.write(b,0,n);}}
 @Override protected void onActivityResult(int r,int ok,Intent d){super.onActivityResult(r,ok,d);if(ok!=RESULT_OK||d==null)return;if(r==12){createZip(d);return;}if(d.getData()==null)return;Uri u=d.getData();if(r==11&&result!=null){File file=result;state(true,"Saving…");io.execute(()->{try(InputStream in=new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(u,"w")){copy(in,out,Long.MAX_VALUE);report("Saved");}catch(Exception e){report("Save failed: "+e.getMessage());}});return;}if(r!=10)return;discard();int op=selected;char[] pass=password.getText().toString().toCharArray();password.setText("");if(op!=2&&pass.length<8){Arrays.fill(pass,'\0');state(false,"Password must have at least eight characters");return;}state(true,"Processing…");String sourceName=name(u);io.execute(()->{File tmp=null,out=null,dir=null;try{tmp=File.createTempFile("tools-in-",".tmp",getCacheDir());try(InputStream in=getContentResolver().openInputStream(u);OutputStream os=new FileOutputStream(tmp)){copy(in,os,op==2?512L*1024*1024:FileTools.VAULT_MAX+(op==1?FileTools.VAULT_OVERHEAD:0));}if(op==2){dir=new File(getCacheDir(),"zip-"+UUID.randomUUID());int n=FileTools.extractZip(tmp,dir);String folder="XDownloadPro/Extracted/"+UUID.randomUUID().toString().substring(0,8);java.util.ArrayList<Uri> created=new java.util.ArrayList<>();try{publishTree(dir,folder,created);}catch(Exception e){for(Uri x:created)try{getContentResolver().delete(x,null,null);}catch(Exception ignored){}throw e;}report(n+" ZIP entries extracted to Downloads/"+folder);}else{out=File.createTempFile("vault-",".tmp",getCacheDir());FileTools.crypt(tmp,out,pass,op==0);File done=out;out=null;String dest=op==0?sourceName+".xdvault":sourceName.endsWith(".xdvault")?sourceName.substring(0,sourceName.length()-8):sourceName+".decrypted";runOnUiThread(()->{if(dead){done.delete();return;}if(result!=null)result.delete();result=done;resultName=dest;state(false,"Ready to save");});}}catch(Exception e){report("Failed: "+e.getMessage());}finally{Arrays.fill(pass,'\0');if(tmp!=null)tmp.delete();if(out!=null)out.delete();if(dir!=null)FileTools.deleteTree(dir);}});}
 void discard(){if(result!=null){result.delete();result=null;}save.setEnabled(false);}
 void createZip(Intent data){LinkedHashSet<Uri> list=new LinkedHashSet<>();if(data.getData()!=null)list.add(data.getData());ClipData clip=data.getClipData();if(clip!=null){if(clip.getItemCount()>100){state(false,"Select at most 100 files");return;}for(int i=0;i<clip.getItemCount();i++){Uri u=clip.getItemAt(i).getUri();if(u!=null)list.add(u);}}if(list.isEmpty()||list.size()>100){state(false,"Select 1–100 files");return;}discard();state(true,"Creating ZIP…");io.execute(()->{File tmp=null;try{tmp=File.createTempFile("tools-zip-",".zip",getCacheDir());HashSet<String> used=new HashSet<>();long total=0;byte[] buf=new byte[65536];try(java.util.zip.ZipOutputStream out=new java.util.zip.ZipOutputStream(new BufferedOutputStream(new FileOutputStream(tmp)))){for(Uri u:list){String entry=FileTools.uniqueEntry(name(u),used);out.putNextEntry(new java.util.zip.ZipEntry(entry));try(InputStream in=getContentResolver().openInputStream(u)){if(in==null)throw new IOException("Cannot access file");int n;while((n=in.read(buf))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException("Cancelled");total+=n;if(total>512L*1024*1024||getCacheDir().getUsableSpace()<16L*1024*1024)throw new IOException("ZIP size or storage limit");out.write(buf,0,n);}}out.closeEntry();}}File done=tmp;tmp=null;runOnUiThread(()->{if(dead){done.delete();return;}result=done;resultName="XDownload-files.zip";state(false,"ZIP ready: "+MainActivity.size(done.length()));});}catch(Exception ex){report("ZIP failed: "+ex.getMessage());}finally{if(tmp!=null)tmp.delete();}});}
 void publishTree(File dir,String folder,java.util.List<Uri> created)throws Exception{File[] files=dir.listFiles();if(files==null)return;for(File f:files){if(f.isDirectory()){publishTree(f,folder+"/"+HttpEngine.safeName(f.getName()),created);continue;}ContentValues v=new ContentValues();v.put(MediaStore.MediaColumns.DISPLAY_NAME,HttpEngine.safeName(f.getName()));v.put(MediaStore.MediaColumns.MIME_TYPE,"application/octet-stream");v.put(MediaStore.MediaColumns.RELATIVE_PATH,Environment.DIRECTORY_DOWNLOADS+"/"+folder);v.put(MediaStore.MediaColumns.IS_PENDING,1);Uri u=getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);if(u==null)throw new IOException("Cannot create extracted file");created.add(u);try(InputStream in=new FileInputStream(f);OutputStream out=getContentResolver().openOutputStream(u,"w")){copy(in,out,Long.MAX_VALUE);}ContentValues ready=new ContentValues();ready.put(MediaStore.MediaColumns.IS_PENDING,0);if(getContentResolver().update(u,ready,null,null)!=1)throw new IOException("Cannot publish extracted file");}}
 void report(String s){runOnUiThread(()->{if(!dead)state(false,s);});}
 @Override public void onDestroy(){dead=true;io.shutdownNow();if(result!=null)result.delete();super.onDestroy();}
}